/* 학습 해설
 * DRM·KMS · 화면 상태와 원자적 커밋
 * 여러 디스플레이 요소의 설정을 모순 없이 검증하고 변경해야 합니다.
 * KMS는 connector·CRTC·plane 등의 상태를 관리합니다. atomic 방식은 새 상태를 준비·검증한 뒤 커밋합니다. GPU 렌더링 작업과 디스플레이 스캔아웃의 역할은 다릅니다.
 * 모드 설정과 렌더링을 구분하고 버퍼·fence 수명을 확인합니다. atomic이라는 말이 CPU atomic 정수 연산 하나로 전체 변경한다는 뜻은 아닙니다.
 */
drm_atomic_state_init(struct drm_device *dev, struct drm_atomic_state *state)
{
	kref_init(&state->ref);

	/* TODO legacy paths should maybe do a better job about
	 * setting this appropriately?
	 */
	state->allow_modeset = true;

	state->crtcs = kcalloc(dev->mode_config.num_crtc,
			       sizeof(*state->crtcs), GFP_KERNEL);
	if (!state->crtcs)
		goto fail;
	state->planes = kcalloc(dev->mode_config.num_total_plane,
				sizeof(*state->planes), GFP_KERNEL);
	if (!state->planes)
		goto fail;

	/*
	 * Because drm_atomic_state can be committed asynchronously we need our
	 * own reference and cannot rely on the on implied by drm_file in the
	 * ioctl call.
	 */
	drm_dev_get(dev);
	state->dev = dev;

