/* 학습 해설
 * DMA-BUF·Fence · 장치 사이 버퍼 공유
 * GPU·카메라·디스플레이가 같은 버퍼를 쓸 때 복사와 수명·완료 관리를 조절해야 합니다.
 * DMA-BUF는 버퍼 export·import·attachment·매핑 수명을 표현합니다. fence는 비동기 작업의 완료를 나타냅니다. 공유 가능성과 CPU·장치 동기화가 자동으로 모두 해결되는 것은 아닙니다.
 * attach·map·unmap·detach 규약과 fence 대기를 확인합니다. 한 장치가 쓰는 도중 다른 장치가 읽지 않도록 접근 순서를 설계합니다.
 */
struct dma_buf_attachment *dma_buf_attach(struct dma_buf *dmabuf,
					  struct device *dev)
{
	return dma_buf_dynamic_attach(dmabuf, dev, NULL, NULL);
}
EXPORT_SYMBOL_NS_GPL(dma_buf_attach, DMA_BUF);

static void __unmap_dma_buf(struct dma_buf_attachment *attach,
			    struct sg_table *sg_table,
			    enum dma_data_direction direction)
{
	/* uses XOR, hence this unmangles */
	mangle_sg_table(sg_table);

	attach->dmabuf->ops->unmap_dma_buf(attach, sg_table, direction);
}

/**
 * dma_buf_detach - Remove the given attachment from dmabuf's attachments list
 * @dmabuf:	[in]	buffer to detach from.
 * @attach:	[in]	attachment to be detached; is free'd after this call.
 *
 * Clean up a device attachment obtained by calling dma_buf_attach().
 *
 * Optionally this calls &dma_buf_ops.detach for device-specific detach.
 */

