 * ALSA PCM · 오디오 링과 XRUN
 * 정해진 속도로 소비·생산되는 오디오 샘플을 지속적으로 공급해야 합니다.
 * PCM은 링 버퍼·하드웨어 위치·애플리케이션 위치·period를 관리합니다. 재생에서 데이터 공급이 늦으면 underrun, 녹음에서 소비가 늦으면 overrun이 발생할 수 있습니다.
 * period와 전체 버퍼 크기의 지연·부하 교환을 이해합니다. 작은 버퍼가 언제나 안전하고 큰 버퍼가 언제나 저지연인 것은 아닙니다.
 */
void snd_pcm_period_elapsed(struct snd_pcm_substream *substream)
{
	if (snd_BUG_ON(!substream))
		return;

	guard(pcm_stream_lock_irqsave)(substream);
	snd_pcm_period_elapsed_under_stream_lock(substream);
}
EXPORT_SYMBOL(snd_pcm_period_elapsed);

