/* 학습 해설
 * Input·Evdev · 입력 사건 전달
 * 키보드·마우스·터치 장치 사건을 일관된 사용자 인터페이스로 전달해야 합니다.
 * input core가 사건 type·code·value와 동기화 경계를 처리해 handler에 전달합니다. evdev는 사용자 공간 이벤트 읽기 경로를 제공합니다. 상태와 사건의 경계를 구분해야 합니다.
 * EV_KEY·EV_ABS·EV_REL·SYN_REPORT 의미를 확인합니다. 큐 손실 시에는 현재 상태 재동기화가 필요할 수 있습니다.
 */
void input_event(struct input_dev *dev,
		 unsigned int type, unsigned int code, int value)
{
	unsigned long flags;

	if (is_event_supported(type, dev->evbit, EV_MAX)) {

		spin_lock_irqsave(&dev->event_lock, flags);
		input_handle_event(dev, type, code, value);
		spin_unlock_irqrestore(&dev->event_lock, flags);
	}
}
EXPORT_SYMBOL(input_event);

/**
 * input_inject_event() - send input event from input handler
 * @handle: input handle to send event through
 * @type: type of the event
 * @code: event code
 * @value: value of the event
 *
 * Similar to input_event() but will ignore event if device is
 * "grabbed" and handle injecting event is not the one that owns
 * the device.
 */
void input_inject_event(struct input_handle *handle,

