/* 학습 해설
 * I2C·SPI · 직렬 버스 전송
 * 센서와 주변 칩의 레지스터를 직렬 버스로 읽고 써야 합니다.
 * I2C는 주소와 메시지 묶음을, SPI는 chip select·클럭·전송 구성을 사용합니다. 전송 성공 개수·부분 처리·버스 제약을 확인해야 하며 장치 레지스터 규약은 버스 API와 별도입니다.
 * I2C 전송 반환을 바이트 수로 오해하지 않습니다. SPI의 mode·속도·bits_per_word를 장치 규격에 맞춥니다.
 */
int i2c_transfer(struct i2c_adapter *adap, struct i2c_msg *msgs, int num)
{
	int ret;

	/* REVISIT the fault reporting model here is weak:
	 *
	 *  - When we get an error after receiving N bytes from a slave,
	 *    there is no way to report "N".
	 *
	 *  - When we get a NAK after transmitting N bytes to a slave,
	 *    there is no way to report "N" ... or to let the master
	 *    continue executing the rest of this combined message, if
	 *    that's the appropriate response.
	 *
	 *  - When for example "num" is two and we successfully complete
	 *    the first message but get an error part way through the
	 *    second, it's unclear whether that should be reported as
	 *    one (discarding status on the second message) or errno
	 *    (discarding status on the first one).
	 */
	ret = __i2c_lock_bus_helper(adap);
	if (ret)
		return ret;

	ret = __i2c_transfer(adap, msgs, num);
	i2c_unlock_bus(adap, I2C_LOCK_SEGMENT);

