/* 학습 해설
 * GPIO·Pinctrl · 핀 기능과 논리 값
 * 보드의 핀을 주변 기능 또는 디지털 입출력으로 설정해야 합니다.
 * pinctrl은 핀 기능·설정을, GPIO descriptor는 선의 방향·논리 값 등을 관리합니다. active-low 논리와 물리 전압은 다르며 일부 컨트롤러 접근은 잠들 수 있습니다.
 * descriptor API와 can_sleep 변형을 맞춰 사용합니다. GPIO 번호·극성·핀 기능을 보드 규격에 맞추며 실제 핀을 임의 구동하는 실험은 요구하지 않습니다.
 */
int gpiod_get_value(const struct gpio_desc *desc)
{
	int value;

	VALIDATE_DESC(desc);
	/* Should be using gpiod_get_value_cansleep() */
	WARN_ON(desc->gdev->can_sleep);

	value = gpiod_get_raw_value_commit(desc);
	if (value < 0)
		return value;

	if (test_bit(FLAG_ACTIVE_LOW, &desc->flags))
		value = !value;

	return value;
}
EXPORT_SYMBOL_GPL(gpiod_get_value);

