/* 학습 해설
 * TTY·Line Discipline · 터미널 바이트 처리
 * 직렬·터미널 입력에 줄 편집·에코·신호·원시 모드 같은 동작을 적용해야 합니다.
 * TTY 드라이버와 line discipline이 장치 바이트와 사용자 읽기 사이의 처리를 나눕니다. canonical 모드는 줄 단위 처리 등을 제공하고 raw 설정은 변환·에코 등을 줄입니다.
 * termios 설정과 stty -a를 조회합니다. 터미널에서 Ctrl-C가 단순 문자 표시와 시그널 생성으로 달라지는 조건을 확인합니다.
 */
n_tty_receive_buf_common(struct tty_struct *tty, const u8 *cp, const u8 *fp,
			 size_t count, bool flow)
{
	struct n_tty_data *ldata = tty->disc_data;
	size_t n, rcvd = 0;
	int room, overflow;

	down_read(&tty->termios_rwsem);

	do {
		/*
		 * When PARMRK is set, each input char may take up to 3 chars
		 * in the read buf; reduce the buffer space avail by 3x
		 *
		 * If we are doing input canonicalization, and there are no
		 * pending newlines, let characters through without limit, so
		 * that erase characters will be handled.  Other excess
		 * characters will be beeped.
		 *
		 * paired with store in *_copy_from_read_buf() -- guarantees
		 * the consumer has loaded the data in read_buf up to the new
		 * read_tail (so this producer will not overwrite unread data)
		 */
		size_t tail = smp_load_acquire(&ldata->read_tail);

		room = N_TTY_BUF_SIZE - (ldata->read_head - tail);

