/* 학습 해설
 * 키링 · 커널의 키·자격 수명
 * 인증 자료와 키를 권한·만료·참조 규약 아래에서 공유해야 합니다.
 * key 객체는 타입·payload·권한·상태와 수명을 갖고 keyring이 검색·연결을 제공합니다. revoke·expire·invalidate는 단순 메모리 삭제와 다른 상태 의미를 가집니다.
 * 소유·권한·세션 범위와 payload 타입을 확인합니다. 키링이 있다는 사실만으로 모든 키가 하드웨어에 영구 안전 보관되는 것은 아닙니다.
 */
struct key *key_alloc(struct key_type *type, const char *desc,
		      kuid_t uid, kgid_t gid, const struct cred *cred,
		      key_perm_t perm, unsigned long flags,
		      struct key_restriction *restrict_link)
{
	struct key_user *user = NULL;
	struct key *key;
	size_t desclen, quotalen;
	int ret;
	unsigned long irqflags;

	key = ERR_PTR(-EINVAL);
	if (!desc || !*desc)
		goto error;

	if (type->vet_description) {
		ret = type->vet_description(desc);
		if (ret < 0) {
			key = ERR_PTR(ret);
			goto error;
		}
	}

	desclen = strlen(desc);
	quotalen = desclen + 1 + type->def_datalen;

