/* 학습 해설
 * KUnit·Selftests · 커널 기능 검증
 * 변경한 커널 코드의 작은 동작과 사용자 ABI를 반복 검증해야 합니다.
 * KUnit은 커널 안의 단위 테스트를, selftests는 사용자 공간과 커널 인터페이스의 테스트를 제공합니다. assertion·fixture·격리·환경 의존을 설계하며 통과가 모든 상황의 정답을 뜻하지는 않습니다.
 * 작은 불변식 검증과 실제 ABI 시나리오를 구분합니다. 실행 환경·설정·skip 사유와 실패 결과를 함께 기록합니다.
 */
int kunit_run_tests(struct kunit_suite *suite)
{
	char param_desc[KUNIT_PARAM_DESC_SIZE];
	struct kunit_case *test_case;
	struct kunit_result_stats suite_stats = { 0 };
	struct kunit_result_stats total_stats = { 0 };

	/* Taint the kernel so we know we've run tests. */
	add_taint(TAINT_TEST, LOCKDEP_STILL_OK);

	if (suite->suite_init) {
		suite->suite_init_err = suite->suite_init(suite);
		if (suite->suite_init_err) {
			kunit_err(suite, KUNIT_SUBTEST_INDENT
				  "# failed to initialize (%d)", suite->suite_init_err);
			goto suite_end;
		}
	}

	kunit_print_suite_start(suite);

	kunit_suite_for_each_test_case(suite, test_case) {
		struct kunit test = { .param_value = NULL, .param_index = 0 };
		struct kunit_result_stats param_stats = { 0 };

		kunit_init_test(&test, test_case->name, test_case->log);

