/* 학습 해설
 * AES·라운드 변환과 키 스케줄
 * 블록 암호 API의 이름뿐 아니라 한 블록이 어떤 계산을 거쳐 암호문이 되는지 알아야 합니다.
 * AES는 16바이트 블록을 4×4 바이트 상태로 표현합니다. SubBytes가 비선형 치환, ShiftRows가 위치 변경, MixColumns가 유한체 선형 결합, AddRoundKey가 라운드 키 XOR을 수행합니다. 키 길이 128·192·256비트에 따라 10·12·14라운드이며 마지막 라운드는 MixColumns를 생략합니다.
 * 실제 응용에서는 검토된 Crypto API 구현과 적합한 모드를 사용합니다. AES 한 블록의 계산만으로 긴 메시지의 모드·nonce·무결성이 결정되지는 않습니다.
 */
static void crypto_aes_encrypt(struct crypto_tfm *tfm, u8 *out, const u8 *in)
{
	const struct crypto_aes_ctx *ctx = crypto_tfm_ctx(tfm);
	u32 b0[4], b1[4];
	const u32 *kp = ctx->key_enc + 4;
	const int key_len = ctx->key_length;

	b0[0] = ctx->key_enc[0] ^ get_unaligned_le32(in);
	b0[1] = ctx->key_enc[1] ^ get_unaligned_le32(in + 4);
	b0[2] = ctx->key_enc[2] ^ get_unaligned_le32(in + 8);
	b0[3] = ctx->key_enc[3] ^ get_unaligned_le32(in + 12);

	if (key_len > 24) {
		f_nround(b1, b0, kp);
		f_nround(b0, b1, kp);
	}

	if (key_len > 16) {
		f_nround(b1, b0, kp);
		f_nround(b0, b1, kp);
	}

	f_nround(b1, b0, kp);
	f_nround(b0, b1, kp);
	f_nround(b1, b0, kp);
	f_nround(b0, b1, kp);

