/* 학습 해설
 * ChaCha20·ARX와 키스트림
 * 스트림 암호가 평문에 적용할 키스트림을 어떤 정수 연산으로 만드는지 이해해야 합니다.
 * 16개의 32비트 word에 상수·키·카운터·nonce를 배치합니다. quarter round가 modulo 2^32 덧셈·XOR·회전을 사용하며 열·대각선 라운드를 반복합니다. 원래 상태를 더한 64바이트 출력을 평문과 XOR합니다. 같은 키의 nonce·카운터 중복은 키스트림을 재사용하게 합니다.
 * nonce·카운터 중복과 카운터 넘침을 피합니다. 암호화만으로 인증이 생기지 않으므로 인증 암호 구성을 확인합니다. 코어 함수의 라운드·출력·카운터 증가를 구분합니다.
 */
void chacha_block_generic(u32 *state, u8 *stream, int nrounds)
{
	u32 x[16];
	int i;

	memcpy(x, state, 64);

	chacha_permute(x, nrounds);

	for (i = 0; i < ARRAY_SIZE(x); i++)
		put_unaligned_le32(x[i] + state[i], &stream[i * sizeof(u32)]);

	state[12]++;
}
EXPORT_SYMBOL(chacha_block_generic);

