/* 학습 해설
 * SHA-256·메시지 확장과 압축 함수
 * 해시 함수가 임의 길이 입력을 고정 길이 요약으로 바꾸는 계산을 이해해야 합니다.
 * 512비트 블록의 32비트 word 16개를 64개 스케줄로 확장합니다. 회전·shift·XOR·Ch·Maj·modulo 덧셈을 사용하는 64라운드가 여덟 상태 word를 갱신합니다. Padding과 원래 길이를 반영한 뒤 256비트 결과를 출력합니다.
 * init·update·final을 사용하고 해시·암호화·키 기반 인증을 구분합니다. 비밀 접두사를 그냥 붙여 해시한 값을 HMAC과 동일하다고 가정하지 않습니다.
 */
static void sha256_transform(u32 *state, const u8 *input, u32 *W)
{
	u32 a, b, c, d, e, f, g, h;
	int i;

	/* load the input */
	for (i = 0; i < 16; i += 8) {
		LOAD_OP(i + 0, W, input);
		LOAD_OP(i + 1, W, input);
		LOAD_OP(i + 2, W, input);
		LOAD_OP(i + 3, W, input);
		LOAD_OP(i + 4, W, input);
		LOAD_OP(i + 5, W, input);
		LOAD_OP(i + 6, W, input);
		LOAD_OP(i + 7, W, input);
	}

	/* now blend */
	for (i = 16; i < 64; i += 8) {
		BLEND_OP(i + 0, W);
		BLEND_OP(i + 1, W);
		BLEND_OP(i + 2, W);
		BLEND_OP(i + 3, W);
		BLEND_OP(i + 4, W);
		BLEND_OP(i + 5, W);
		BLEND_OP(i + 6, W);

