/* 학습 해설
 * AEAD·인증 암호와 Nonce
 * 데이터를 숨기는 것과 변조를 검출하는 것을 명확한 규약으로 결합해야 합니다.
 * GCM은 카운터 모드 암호화와 GF(2^128)의 GHASH 인증을 결합합니다. AAD는 암호화하지 않아도 인증에 포함하는 데이터입니다. 암호문·AAD·길이·nonce가 tag 계산에 관련되며 같은 키에서 nonce 중복을 피해야 합니다.
 * 키·nonce·AAD 길이·tag 길이·버퍼 배치를 맞춥니다. 복호화 인증 실패이면 버퍼를 정상 평문으로 처리하지 않습니다. 암·복호 요청의 cryptlen 규약을 구분합니다.
 */
static int crypto_gcm_encrypt(struct aead_request *req)
{
	struct crypto_gcm_req_priv_ctx *pctx = crypto_gcm_reqctx(req);
	struct skcipher_request *skreq = &pctx->u.skreq;
	u32 flags = aead_request_flags(req);

	crypto_gcm_init_common(req);
	crypto_gcm_init_crypt(req, req->cryptlen);
	skcipher_request_set_callback(skreq, flags, gcm_encrypt_done, req);

	return crypto_skcipher_encrypt(skreq) ?:
	       gcm_encrypt_continue(req, flags);
}

static int crypto_gcm_verify(struct aead_request *req)
{
	struct crypto_gcm_req_priv_ctx *pctx = crypto_gcm_reqctx(req);
	struct crypto_aead *aead = crypto_aead_reqtfm(req);
	u8 *auth_tag = pctx->auth_tag;
	u8 *iauth_tag = pctx->iauth_tag;
	unsigned int authsize = crypto_aead_authsize(aead);
	unsigned int cryptlen = req->cryptlen - authsize;

	crypto_xor(auth_tag, iauth_tag, 16);
	scatterwalk_map_and_copy(iauth_tag, req->src,
				 req->assoclen + cryptlen, authsize, 0);

