/* 학습 해설
 * ECN·드롭 대신 혼잡 알림
 * 혼잡을 알리기 위해 항상 패킷을 버리지 않고 명시적 표시를 전달할 수 있습니다.
 * ECN 지원을 협상한 전송과 네트워크가 ECT·CE 등의 표시를 사용합니다. TCP 수신자는 CE를 관찰해 피드백을 전달하고 송신자가 혼잡 제어에 반영합니다. IP의 혼잡 표시와 TCP의 ECE·CWR 역할을 구분합니다.
 * 전송·큐·경로의 지원 상태를 함께 확인합니다. ECN이 활성이라고 손실이 절대 없거나 모든 라우터가 항상 표시하는 것은 아닙니다.
 */
static void tcp_ecn_check_ce(struct sock *sk, const struct sk_buff *skb)
{
	if (tcp_sk(sk)->ecn_flags & TCP_ECN_OK)
		__tcp_ecn_check_ce(sk, skb);
}

static void tcp_ecn_rcv_synack(struct tcp_sock *tp, const struct tcphdr *th)
{
	if ((tp->ecn_flags & TCP_ECN_OK) && (!th->ece || th->cwr))
		tp->ecn_flags &= ~TCP_ECN_OK;
}

static void tcp_ecn_rcv_syn(struct tcp_sock *tp, const struct tcphdr *th)
{
	if ((tp->ecn_flags & TCP_ECN_OK) && (!th->ece || !th->cwr))
		tp->ecn_flags &= ~TCP_ECN_OK;
}

static bool tcp_ecn_rcv_ecn_echo(const struct tcp_sock *tp, const struct tcphdr *th)
{
	if (th->ece && !th->syn && (tp->ecn_flags & TCP_ECN_OK))
		return true;
	return false;
}

