/* 학습 해설
 * TCP Reno·AIMD의 계산
 * 단순한 혼잡 제어부터 증가·감소량을 계산하면 더 복잡한 모듈을 이해하기 쉬워집니다.
 * Reno는 slow start와 혼잡 회피를 구분합니다. 혼잡 회피의 additive increase와 혼잡 시 multiplicative decrease가 AIMD의 기본 형태입니다. 이 구현의 ssthresh는 cwnd 절반과 최소 2를 고려하며 모든 상태의 실제 cwnd가 항상 즉시 절반이 되는 것은 아닙니다.
 * cwnd·ssthresh·ACK 수의 단위를 구분하고 제한·slow start·회복 경로를 함께 읽습니다. 이 기본 모듈이 모든 소켓의 기본 정책이라고 가정하지 않습니다.
 */
__bpf_kfunc void tcp_reno_cong_avoid(struct sock *sk, u32 ack, u32 acked)
{
	struct tcp_sock *tp = tcp_sk(sk);

	if (!tcp_is_cwnd_limited(sk))
		return;

	/* In "safe" area, increase. */
	if (tcp_in_slow_start(tp)) {
		acked = tcp_slow_start(tp, acked);
		if (!acked)
			return;
	}
	/* In dangerous area, increase slowly. */
	tcp_cong_avoid_ai(tp, tcp_snd_cwnd(tp), acked);
}
EXPORT_SYMBOL_GPL(tcp_reno_cong_avoid);

/* Slow start threshold is half the congestion window (min 2) */
__bpf_kfunc u32 tcp_reno_ssthresh(struct sock *sk)
{
	const struct tcp_sock *tp = tcp_sk(sk);

	return max(tcp_snd_cwnd(tp) >> 1U, 2U);
}
EXPORT_SYMBOL_GPL(tcp_reno_ssthresh);

