/* 학습 해설
 * Rseq·CPU 이동과 재시작 구간
 * CPU별 데이터를 빠르게 갱신할 때 계산 중 CPU가 바뀌면 잘못된 CPU의 상태를 수정할 수 있습니다.
 * 사용자 공간이 rseq_cs에 시작 주소·커밋 뒤 경계·중단 주소를 등록합니다. 선점·신호·CPU 이동 뒤 커널은 저장된 명령 주소가 구간 안인지 검사하고 필요한 경우 abort_ip로 복귀 위치를 바꿉니다. 성공 커밋 이전의 계산을 재시작하는 협력 규약입니다.
 * 지원 여부를 확인하고 검토된 라이브러리의 rseq 등록·구간 규약을 사용합니다. 중단 가능한 구간에서 이미 외부에 공개한 여러 변경을 커널이 자동 취소한다고 가정하지 않습니다.
 */
static int rseq_ip_fixup(struct pt_regs *regs)
{
	unsigned long ip = instruction_pointer(regs);
	struct task_struct *t = current;
	struct rseq_cs rseq_cs;
	int ret;

	ret = rseq_get_rseq_cs(t, &rseq_cs);
	if (ret)
		return ret;

	/*
	 * Handle potentially not being within a critical section.
	 * If not nested over a rseq critical section, restart is useless.
	 * Clear the rseq_cs pointer and return.
	 */
	if (!in_rseq_cs(ip, &rseq_cs))
		return clear_rseq_cs(t);
	ret = rseq_need_restart(t, rseq_cs.flags);
	if (ret <= 0)
		return ret;
	ret = clear_rseq_cs(t);
	if (ret)
		return ret;
	trace_rseq_ip_fixup(ip, rseq_cs.start_ip, rseq_cs.post_commit_offset,
			    rseq_cs.abort_ip);

