/* 학습 해설
 * Cache Coherency·캐시 라인 공유
 * 여러 CPU가 같은 메모리를 수정할 때 캐시 라인의 이동 비용이 동기화 성능을 좌우합니다.
 * 캐시 일관성은 같은 라인의 쓰기가 다른 CPU 관찰과 일관되도록 관리하는 하드웨어 규약입니다. qspinlock은 경쟁이 커지면 MCS 노드 기반 큐를 활용해 모두가 한 공유 word만 반복 수정하는 부담을 줄입니다. 캐시 일관성과 서로 다른 주소 사이 메모리 순서 보장은 구분해야 합니다.
 * 공유 변수의 lock과 원자 연산을 규약대로 사용합니다. 다른 변수라도 한 캐시 라인에 있으면 false sharing이 생길 수 있어 배치·padding·CPU별 데이터를 측정하며 선택합니다.
 */
void __lockfunc queued_spin_lock_slowpath(struct qspinlock *lock, u32 val)
{
	struct mcs_spinlock *prev, *next, *node;
	u32 old, tail;
	int idx;

	BUILD_BUG_ON(CONFIG_NR_CPUS >= (1U << _Q_TAIL_CPU_BITS));

	if (pv_enabled())
		goto pv_queue;

	if (virt_spin_lock(lock))
		return;

	/*
	 * Wait for in-progress pending->locked hand-overs with a bounded
	 * number of spins so that we guarantee forward progress.
	 *
	 * 0,1,0 -> 0,0,1
	 */
	if (val == _Q_PENDING_VAL) {
		int cnt = _Q_PENDING_LOOPS;
		val = atomic_cond_read_relaxed(&lock->val,
					       (VAL != _Q_PENDING_VAL) || !cnt--);
	}

