/* 학습 해설
 * NUMA 정책·노드 선택과 mbind
 * CPU가 어느 메모리 노드에 접근하는지에 따라 지연과 대역폭이 달라져 배치 정책이 필요합니다.
 * NUMA는 메모리 노드별 접근 거리가 다른 구조입니다. mbind는 주소 범위에 메모리 정책을 설정하며 bind·preferred·interleave는 노드 선택 방식이 다릅니다. 이미 존재하는 페이지를 이동할지는 별도 flags·권한·이동 가능성에 따릅니다.
 * Linux에서 numactl --hardware로 토폴로지를 보고 정책과 CPU affinity를 함께 검토합니다. mbind의 페이지 정렬 범위·노드 마스크·mode·이동 flags를 확인하고 반환 오류를 처리합니다.
 */
static long do_mbind(unsigned long start, unsigned long len,
		     unsigned short mode, unsigned short mode_flags,
		     nodemask_t *nmask, unsigned long flags)
{
	struct mm_struct *mm = current->mm;
	struct vm_area_struct *vma, *prev;
	struct vma_iterator vmi;
	struct migration_mpol mmpol;
	struct mempolicy *new;
	unsigned long end;
	long err;
	long nr_failed;
	LIST_HEAD(pagelist);

	if (flags & ~(unsigned long)MPOL_MF_VALID)
		return -EINVAL;
	if ((flags & MPOL_MF_MOVE_ALL) && !capable(CAP_SYS_NICE))
		return -EPERM;

	if (start & ~PAGE_MASK)
		return -EINVAL;

	if (mode == MPOL_DEFAULT)
		flags &= ~MPOL_MF_STRICT;

	len = PAGE_ALIGN(len);

