/* 학습 해설
 * DAMON·접근 샘플링과 구간 조절
 * 모든 메모리 접근을 하나씩 기록하면 관찰 비용이 커져 적은 샘플로 사용 경향을 파악해야 합니다.
 * DAMON은 주소 공간을 구간으로 나누어 접근을 샘플링하고 접근 빈도가 비슷한 인접 구간을 합칩니다. 합칠 때 구간 크기를 가중치로 접근 수와 age를 평균합니다. 빈도가 달라지면 구간 조절을 통해 관찰 정확도와 비용을 조절합니다.
 * 지원 커널의 DAMON 관리 인터페이스에서 대상·샘플링·집계 간격과 구간 수를 설정합니다. 샘플 기반 수치를 모든 실제 접근의 정확한 횟수로 해석하지 않습니다. 적용 전 관찰 비용과 구간 단위를 확인합니다.
 */
static void damon_merge_regions_of(struct damon_target *t, unsigned int thres,
				   unsigned long sz_limit)
{
	struct damon_region *r, *prev = NULL, *next;

	damon_for_each_region_safe(r, next, t) {
		if (abs(r->nr_accesses - r->last_nr_accesses) > thres)
			r->age = 0;
		else
			r->age++;

		if (prev && prev->ar.end == r->ar.start &&
		    abs(prev->nr_accesses - r->nr_accesses) <= thres &&
		    damon_sz_region(prev) + damon_sz_region(r) <= sz_limit)
			damon_merge_two_regions(t, prev, r);
		else
			prev = r;
	}
}

