/* 학습 해설
 * Memblock·초기 부팅 메모리 할당
 * Buddy와 slab allocator가 준비되기 전에도 커널은 페이지 테이블과 초기 자료구조의 공간이 필요합니다.
 * Memblock은 사용 가능한 물리 메모리와 예약 영역을 구간 목록으로 관리합니다. 크기·정렬·주소 범위·노드 조건에 맞는 빈 구간을 찾고 예약해 중복 할당을 막습니다. 일반 실행 시 kmalloc의 동작과 초기 부팅의 물리 주소 할당은 구분합니다.
 * 초기 부팅 코드에서 memblock API의 물리 주소 반환과 가상 주소 반환을 구분합니다. 범위·정렬·노드 fallback·실패값을 확인합니다. slab 준비 이후 경고 경로가 있다는 사실은 일반 코드에서 memblock을 써도 된다는 의미가 아닙니다.
 */
phys_addr_t __init memblock_alloc_range_nid(phys_addr_t size,
					phys_addr_t align, phys_addr_t start,
					phys_addr_t end, int nid,
					bool exact_nid)
{
	enum memblock_flags flags = choose_memblock_flags();
	phys_addr_t found;

	/*
	 * Detect any accidental use of these APIs after slab is ready, as at
	 * this moment memblock may be deinitialized already and its
	 * internal data may be destroyed (after execution of memblock_free_all)
	 */
	if (WARN_ON_ONCE(slab_is_available())) {
		void *vaddr = kzalloc_node(size, GFP_NOWAIT, nid);

		return vaddr ? virt_to_phys(vaddr) : 0;
	}

	if (!align) {
		/* Can't use WARNs this early in boot on powerpc */
		dump_stack();
		align = SMP_CACHE_BYTES;
	}

