/* 학습 해설
 * Kmalloc·크기 클래스와 할당 플래그
 * 커널의 작은 객체 할당은 물리 페이지 하나씩 할당하는 것보다 효율적인 크기별 관리를 사용합니다.
 * kmalloc은 요청 크기와 flags에 맞는 slab cache를 고르고 객체를 할당합니다. 큰 요청은 별도 페이지 할당 경로로 갈 수 있습니다. GFP flags는 잠들 수 있는지·회수와 I/O를 허용하는지 등 문맥의 제약을 표현하며 실패와 수명 관리는 호출자 책임입니다.
 * 일반 잠들 수 있는 문맥의 GFP_KERNEL과 atomic 문맥의 제약을 구분하고 NULL을 검사합니다. 필요한 초기화는 kzalloc 등을 검토하며 사용 뒤 kfree합니다. 큰 연속 할당과 가상 연속인 vmalloc의 용도를 구분합니다.
 */
void *__kmalloc_noprof(size_t size, gfp_t flags)
{
	return __do_kmalloc_node(size, NULL, flags, NUMA_NO_NODE, _RET_IP_);
}
EXPORT_SYMBOL(__kmalloc_noprof);

void *__kmalloc_node_track_caller_noprof(DECL_BUCKET_PARAMS(size, b), gfp_t flags,
					 int node, unsigned long caller)
{
	return __do_kmalloc_node(size, PASS_BUCKET_PARAM(b), flags, node, caller);

}
EXPORT_SYMBOL(__kmalloc_node_track_caller_noprof);

void *__kmalloc_cache_noprof(struct kmem_cache *s, gfp_t gfpflags, size_t size)
{
	void *ret = slab_alloc_node(s, NULL, gfpflags, NUMA_NO_NODE,
					    _RET_IP_, size);

	trace_kmalloc(_RET_IP_, ret, size, s->size, gfpflags, NUMA_NO_NODE);

	ret = kasan_kmalloc(s, ret, size, gfpflags);
	return ret;
}
EXPORT_SYMBOL(__kmalloc_cache_noprof);

