/* 학습 해설
 * Bcachefs·버전과 B-tree
 * 변하는 저장 메타데이터를 B-tree에서 읽을 때 키의 위치·버전·snapshot·동시 변경을 함께 고려해야 합니다.
 * Bcachefs의 B-tree iterator는 inode·offset·snapshot 등이 들어가는 키 위치와 transaction 경로를 가지고 탐색합니다. peek_upto는 현재 위치 이상에서 한계 이하의 키를 찾습니다. 트랜잭션 재시작 오류와 실제 키 없음은 구분하며 snapshot의 가시성 규약도 따릅니다.
 * bpos·bkey_s_c·btree_iter·btree_trans의 역할을 구분합니다. 반환된 키의 수명과 bkey_err를 확인하며 transaction이 재시작되면 필요한 탐색을 규약대로 다시 수행합니다.
 */
struct bkey_s_c bch2_btree_iter_peek_upto(struct btree_iter *iter, struct bpos end)
{
	struct btree_trans *trans = iter->trans;
	struct bpos search_key = btree_iter_search_key(iter);
	struct bkey_s_c k;
	struct bpos iter_pos;
	int ret;

	bch2_trans_verify_not_unlocked(trans);
	EBUG_ON((iter->flags & BTREE_ITER_filter_snapshots) && bkey_eq(end, POS_MAX));

	if (iter->update_path) {
		bch2_path_put_nokeep(trans, iter->update_path,
				     iter->flags & BTREE_ITER_intent);
		iter->update_path = 0;
	}

	bch2_btree_iter_verify_entry_exit(iter);

	while (1) {
		k = __bch2_btree_iter_peek(iter, search_key);
		if (unlikely(!k.k))
			goto end;
		if (unlikely(bkey_err(k)))
			goto out_no_locked;

