/* 학습 해설
 * Fscrypt·파일 이름과 내용의 암호화
 * 파일시스템 암호화는 파일 내용뿐 아니라 이름·정책·키의 수명과 접근 조건을 관리해야 합니다.
 * Fscrypt는 inode의 암호화 context에서 정책을 읽고 master key로 필요한 암호 정보를 준비합니다. 파일시스템이 지원하는 내용·이름 암호화 모드와 IV 규약을 따릅니다. 디스크의 암호화 정책이 존재하는 것과 현재 사용 가능한 키가 있는 것은 다릅니다.
 * 지원 파일시스템에서 정책을 설정하고 key 추가·제거와 허용되는 파일 작업을 확인합니다. 암호화된 저장 내용의 비밀성과 메타데이터 노출 범위·무결성 요구를 구분합니다.
 */
int fscrypt_get_encryption_info(struct inode *inode, bool allow_unsupported)
{
	int res;
	union fscrypt_context ctx;
	union fscrypt_policy policy;

	if (fscrypt_has_encryption_key(inode))
		return 0;

	res = inode->i_sb->s_cop->get_context(inode, &ctx, sizeof(ctx));
	if (res < 0) {
		if (res == -ERANGE && allow_unsupported)
			return 0;
		fscrypt_warn(inode, "Error %d getting encryption context", res);
		return res;
	}

	res = fscrypt_policy_from_context(&policy, &ctx, res);
	if (res) {
		if (allow_unsupported)
			return 0;
		fscrypt_warn(inode,
			     "Unrecognized or corrupt encryption context");
		return res;
	}

