/* 학습 해설
 * SquashFS·읽기 전용 압축 파일시스템
 * 배포 이미지의 파일을 작게 묶고 실행 중 변경하지 않는 저장 형식이 필요할 수 있습니다.
 * SquashFS는 파일 데이터와 메타데이터를 압축된 이미지에 저장하고 읽을 때 필요한 블록을 복원합니다. Superblock의 압축 방식·테이블 위치·inode·fragment 정보를 해석합니다. 읽기 전용 이미지 수정과 일반 파일시스템 쓰기는 다른 작업입니다.
 * mksquashfs로 이미지를 만들고 지원 커널에서 읽기 전용으로 마운트합니다. 쓰기 공간이 필요한 경우 별도 상위 계층 등 설계를 사용합니다. 압축 블록 단위의 랜덤 읽기 비용도 측정합니다.
 */
static int squashfs_fill_super(struct super_block *sb, struct fs_context *fc)
{
	struct squashfs_mount_opts *opts = fc->fs_private;
	struct squashfs_sb_info *msblk;
	struct squashfs_super_block *sblk = NULL;
	struct inode *root;
	long long root_inode;
	unsigned short flags;
	unsigned int fragments;
	u64 lookup_table_start, xattr_id_table_start, next_table;
	int err;

	TRACE("Entered squashfs_fill_superblock\n");

	sb->s_fs_info = kzalloc(sizeof(*msblk), GFP_KERNEL);
	if (sb->s_fs_info == NULL) {
		ERROR("Failed to allocate squashfs_sb_info\n");
		return -ENOMEM;
	}
	msblk = sb->s_fs_info;
	msblk->thread_ops = opts->thread_ops;

	msblk->panic_on_errors = (opts->errors == Opt_errors_panic);

	msblk->devblksize = sb_min_blocksize(sb, SQUASHFS_DEVBLK_SIZE);
	msblk->devblksize_log2 = ffz(~msblk->devblksize);

